// 输出所有三位水仙花数
for (int n = 100; n < 1000; n++) {
    int a = n / 100, b = n / 10 % 10, c = n % 10;
    if (a*a*a + b*b*b + c*c*c == n) printf("%d\n", n);
}

// 递推求斐波那契第 n 项（不递归，避免超时）
long long f[100];
f[1] = f[2] = 1;
for (int i = 3; i <= n; i++) f[i] = f[i-1] + f[i-2];
printf("%lld\n", f[n]);

// 选择排序
for (int i = 0; i < n - 1; i++) {
    int k = i;
    for (int j = i + 1; j < n; j++)
        if (a[j] < a[k]) k = j;
    if (k != i) { int t = a[i]; a[i] = a[k]; a[k] = t; }
}

int left = 0, right = n - 1, ans = -1;
while (left <= right) {
    int mid = left + (right - left) / 2;
    if (a[mid] == target) { ans = mid; break; }
    if (a[mid] < target) left = mid + 1;
    else right = mid - 1;
}

int gcd(int a, int b) {
    while (b) { int t = a % b; a = b; b = t; }
    return a;
}
// lcm
long long lcm = (long long)a / gcd(a, b) * b;

