#define CAP 1005
int q[CAP], front = 0, rear = 0;

void push(int x) { q[rear] = x; rear = (rear + 1) % CAP; }
int pop(void) { int x = q[front]; front = (front + 1) % CAP; return x; }
int empty(void) { return front == rear; }

typedef struct Node {
    int val;
    struct Node *next;
} Node;

// 统计每个数字出现次数（key 范围已知时）
int cnt[100005] = {0};
for (int i = 0; i < n; i++) cnt[a[i]]++;
for (int v = 0; v < 100005; v++)
    if (cnt[v]) printf("%d 出现 %d 次\n", v, cnt[v]);

void dfs(int row) {
    if (row == n) { ans++; return; }
    for (int col = 0; col < n; col++) {
        if (used[col]) continue;
        used[col] = 1;
        dfs(row + 1);
        used[col] = 0;      // 撤销
    }
}

// 网格 DFS
int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
void dfs(int x, int y) {
    if (x < 0 || x >= n || y < 0 || y >= m) return;
    if (vis[x][y] || grid[x][y] == 0) return;
    vis[x][y] = 1;
    for (int d = 0; d < 4; d++) dfs(x + dx[d], y + dy[d]);
}

int height(Node *root) {
    if (!root) return 0;
    int l = height(root->left);
    int r = height(root->right);
    return (l > r ? l : r) + 1;
}

// 邻接表（链式前向星）
int head[MAXV], to[MAXE], nxt[MAXE], cnt = 0;
void addEdge(int u, int v) {
    to[++cnt] = v; nxt[cnt] = head[u]; head[u] = cnt;
}
// 无向图要加两次
addEdge(u, v); addEdge(v, u);

int find(int x) {
    return parent[x] == x ? x : (parent[x] = find(parent[x]));
}

// Kruskal 主体
sort(edges, edges + m);
for (int i = 0; i < m && picked < n - 1; i++) {
    int ru = find(edges[i].u), rv = find(edges[i].v);
    if (ru != rv) { parent[ru] = rv; total += edges[i].w; picked++; }
}

// 最大子段和
int best = a[0], cur = a[0];
for (int i = 1; i < n; i++) {
    cur = (cur > 0 ? cur : 0) + a[i];
    if (cur > best) best = cur;
}
